struct MinMax
{
    int min{};
    int max{};
};

MinMax findMinMax(int a, int b, int c)
{
    MinMax result{ a, a };
    if (b < result.min) result.min = b;
    if (c < result.min) result.min = c;
    if (b > result.max) result.max = b;
    if (c > result.max) result.max = c;
    return result;
}

unitTests:
TEST("members") { const MinMax r{ findMinMax(4, 9, 2) }; CHECK_EQ(r.min, 2); CHECK_EQ(r.max, 9); }
TEST("unpacking with structured bindings") { auto [lo, hi]{ findMinMax(-1, -8, -3) }; CHECK_EQ(lo, -8); CHECK_EQ(hi, -1); }
TEST("all the same") { auto [lo, hi]{ findMinMax(5, 5, 5) }; CHECK_EQ(lo, 5); CHECK_EQ(hi, 5); }

